const r = await tools.exec_command({cmd:"rtk proxy python3 - <<'PY'
import subprocess

local = subprocess.check_output([
    "rtk", "proxy", "git", "for-each-ref",
    "--format=%(creatordate:short) %(refname)", "refs/entire/checkpoints",
], text=True)
remote = subprocess.check_output([
    "rtk", "proxy", "git", "ls-remote", "origin", "refs/entire/checkpoints/*",
], text=True)
remote_refs = {line.split()[1] for line in remote.splitlines() if len(line.split()) > 1}
recent_refs = sorted(
    line.split()[1]
    for line in local.splitlines()
    if len(line.split()) > 1 and line.split()[0] >= "2026-09-21"
)
missing = [ref for ref in recent_refs if ref not in remote_refs]
if not missing:
    print("No missing recent checkpoint refs.")
    raise SystemExit(0)
refspecs = [f"{ref}:{ref}" for ref in missing]
print(f"Pushing {len(refspecs)} missing Callisto checkpoint refs only.", flush=True)
result = subprocess.run([
    "rtk", "proxy", "git", "-c", "core.hooksPath=/dev/null", "push", "--porcelain", "origin", *refspecs,
], text=True, stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
print(result.stdout)
if result.returncode:
    raise SystemExit(result.returncode)
verification = subprocess.check_output([
    "rtk", "proxy", "git", "ls-remote", "origin", "refs/entire/checkpoints/*",
], text=True)
remote_after = {line.split()[1] for line in verification.splitlines() if len(line.split()) > 1}
still_missing = [ref for ref in missing if ref not in remote_after]
print(f"Verified: {len(missing) - len(still_missing)}/{len(missing)} refs now on origin.")
if still_missing:
    print("Still missing:\n" + "\n".join(still_missing))
    raise SystemExit(1)
